CREATE TABLE finances.frozen_holding_alerts (
    holding_kind finances.wallet_kind NOT NULL,
    holding_external_id UUID NOT NULL,
    user_id BIGINT NOT NULL REFERENCES system.users (id) ON DELETE CASCADE,
    green BOOLEAN NOT NULL,
    green_since TIMESTAMPTZ,
    alerted_at TIMESTAMPTZ,
    PRIMARY KEY (holding_kind, holding_external_id)
);

CREATE INDEX frozen_holding_alerts_user_id_idx ON finances.frozen_holding_alerts (user_id);
